	base += (n-1)/4*12

	// Offset inside the block
	pos := (n - 1) % 4
	if pos == 1 || pos == 2 {
		base += 6
	}

	// Seat offset within the row
	seatOffset := int64(0)
	switch seat {
	case 'f':
		seatOffset = 1
	case 'e':
		seatOffset = 2
	case 'd':
		seatOffset = 3
	case 'a':
		seatOffset = 4
	case 'b':
		seatOffset = 5
	case 'c':
		seatOffset = 6
	}

	fmt.Println(base + seatOffset)
