package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var s string
	fmt.Fscan(in, &s)

	// Separate row number and seat letter
	n := int64(0)
	for i := 0; i < len(s)-1; i++ {
		n = n*10 + int64(s[i]-'0')
	}
	seat := s[len(s)-1]

	// Determine which attendant serves row n
	// Attendant A: rows 1,2,5,6,9,10,... (pattern 4k+1,4k+2)
	// Attendant B: rows 3,4,7,8,11,12,... (pattern 4k+3,4k+4)
	var baseRow int64
	if n%4 == 1 || n%4 == 2 {
		// Attendant A, base row 1
		baseRow = 1
	} else {
		// Attendant B, base row 3
		baseRow = 3
	}

	// Number of rows this attendant must move forward from its starting row
	// Movement pattern per attendant: 0,0,1,1,4,4,5,5,8,8,... (pairs)
	// For row index r (1-based for that attendant): r=1->row1, r=2->row2, r=3->row5, r=4->row6,...
	// General: row = baseRow + (r-1)/2*4 + (r-1)%2
	// We need r such that row == n.
	// For both attendants, rows come in pairs: (4k+1,4k+2) or (4k+3,4k+4).
	// Index within pair:
	var r int64
	if n%4 == 1 || n%4 == 3 {
		// first in pair
		k := (n - baseRow) / 4
		r = 2*k + 1
	} else {
		// second in pair
		k := (n - 1 - baseRow) / 4
		r = 2*k + 2
	}

	// Total rows moved by this attendant from its start to reach row n
	// Each step between served rows is 1 second per row moved.
	// Movement distance from baseRow to n is simply |n - baseRow|.
	moveTime := n - baseRow

	// Time spent serving previous rows by this attendant:
	// Each row takes 6 seconds to serve.
	servePrevRows := (r - 1) * 6

	// Time within the row for Vasya's seat
	// Serving order: f(1), e(2), d(3), c(4), b(5), a(6)
	var seatTime int64
	switch seat {
	case 'f':
		seatTime = 1
	case 'e':
		seatTime = 2
	case 'd':
		seatTime = 3
	case 'c':
		seatTime = 4
	case 'b':
		seatTime = 5
	case 'a':
		seatTime = 6
	}

	// Total time
	ans := moveTime + servePrevRows + seatTime
	fmt.Println(ans)
}

