func main() {
	in := bufio.NewReader(os.Stdin)
	var n uint64
	var s byte
	fmt.Fscan(in, &n, &s)

	// Determine which attendant serves the row and its index in his sequence
	var k uint64
	if n%2 == 1 {
		// odd row -> first attendant
		k = (n + 1) / 2
	} else {
		// even row -> second attendant
		k = n / 2
	}

	// Time spent before reaching this row:
	// For each row: 6 seconds serving + 1 second moving to next row
	// So before row k: k-1 rows fully served and moved past
	time := (k - 1) * 7

	// Now add time within the row depending on seat
	switch s {
	case 'f':
		time += 1
	case 'e':
		time += 2
	case 'd':
		time += 3
	case 'a':
		time += 4
	case 'b':
		time += 5
	case 'c':
		time += 6
	}

	fmt.Println(time)
}
